  const v=Number(process.env.IA_RETRY_BASE_SEGUNDOS);
  if(Number.isFinite(v)&&v>0) base=Math.floor(v);
  const m=Number(process.env.IA_RETRY_MAX_SEGUNDOS);
  if(Number.isFinite(m)&&m>=base) max=Math.floor(m);
