const log=esc(JSON.stringify({wf:'WF03',acao:'ERRO_IA_CLASSIF',ts:new Date().toISOString(),erro:d.mensagem_erro||'Erro IA',backoff_base:base,backoff_max:max}));
return `WITH atualizada AS (
UPDATE tickets_processados
SET triagem_status=CASE
      WHEN COALESCE(tentativas_ia_classificacao,0)+1 < 3 THEN 'PENDENTE_FILA_IA'
      ELSE 'ERRO_IA'
    END,
    fila_etapa='CLASSIFICACAO',
    fila_enfileirada_em=CASE
      WHEN COALESCE(tentativas_ia_classificacao,0)+1 < 3 THEN NOW()
      ELSE fila_enfileirada_em
    END,
    fila_disponivel_em=CASE
      WHEN COALESCE(tentativas_ia_classificacao,0)+1 < 3
      THEN NOW() + (
        LEAST(${max},${base} * power(2,COALESCE(tentativas_ia_classificacao,0)))::int
        + mod(id + COALESCE(tentativas_ia_classificacao,0),11)
      ) * interval '1 second'
      ELSE fila_disponivel_em
    END,
    fila_liberar_em=NULL,
    fila_reservada_em=NULL,
    ultima_acao_workflow=CASE
      WHEN COALESCE(tentativas_ia_classificacao,0)+1 < 3
      THEN 'WF03_REENFILEIRADO_ERRO_IA'
      ELSE 'ERRO_IA_CLASSIF'
    END,
    ultimo_erro_ia=${esc(d.mensagem_erro || 'Erro IA')},
    tentativas_ia_classificacao=COALESCE(tentativas_ia_classificacao,0)+1,
    tentativas_ia=COALESCE(tentativas_ia,0)+1,
    log_workflow=COALESCE(log_workflow,'[]'::jsonb)||${log}::jsonb,
    atualizado_em=NOW()
WHERE id=${Number(d.chamado?.id)}
RETURNING id,triagem_status,tentativas_ia_classificacao,ultimo_erro_ia,ultima_acao_workflow
), contexto AS (
  SELECT dc.run_id,dc.case_id,dc.episode_id
  FROM dataset_controle dc
  WHERE dc.ticket_id=${Number(d.chamado?.id)}
  ORDER BY dc.id DESC LIMIT 1
), dlq AS (
  INSERT INTO fila_ia_dead_letter(
    ticket_id,etapa,tentativa_numero,erro,run_id,case_id,episode_id,payload_contexto
  )
  SELECT a.id,'CLASSIFICACAO',a.tentativas_ia_classificacao,a.ultimo_erro_ia,
         c.run_id,c.case_id,c.episode_id,
         jsonb_build_object('workflow','WF03','ultima_acao',a.ultima_acao_workflow)
  FROM atualizada a LEFT JOIN contexto c ON TRUE
  WHERE a.triagem_status='ERRO_IA'
  ON CONFLICT(ticket_id,etapa,tentativa_numero) DO UPDATE
  SET erro=EXCLUDED.erro,payload_contexto=EXCLUDED.payload_contexto
  RETURNING id
)
SELECT id,triagem_status,tentativas_ia_classificacao FROM atualizada;`;
})() }}

