  ${esc(erro?'ERRO':'OK')},${esc(c.status_original_nome || c.status_nome || '')},
  NULL,${erro?'TRUE':'FALSE'},${msg?esc(msg):'NULL'},NOW(),NOW()
);
SELECT ${id} AS id,${esc(pred)} AS predicao_observada;
`; })() }}
